from pathlib import Path
import pandas as pd,numpy as np,json
from scipy.stats import norm
b=Path(__file__).resolve().parents[1];root=b.parents[1];d=pd.read_csv(root/'subprojects/original-hybird-extended-oct-2026/data/final_news_v3/NEWS_ARTICLES_FINAL_CALCULATED.csv',float_precision='round_trip');w={'court_ruling':1.,'regulatory':.9,'listing':.8,'delisting':.8,'custody/etf':.8,'hack/outage':.6,'partnership':.6,'exec_comment':.5,'influencer_tweet':.7,'macro':.3,'general_article':.1};src=np.where(d.source.fillna('').str.contains('twitter',case=False),3,2);actor=np.clip(.6*np.log10(1+d.followers_used)/8+.4*src/3,0,1);z=(d.engagement_sum_used-d.engagement_sum_used.mean())/(d.engagement_sum_used.std(ddof=1)+1e-6);velocity=norm.cdf(z);expected=.25*actor+.2*d.reg_access_flag+.15*d.xrp_specificity+.1*d.surprise_flag+.15*velocity+.1*d.event_type.map(w).fillna(.1);age=(pd.to_datetime(d.hour_start_utc,utc=True)-pd.to_datetime(d.published_at_utc,utc=True)).dt.total_seconds()/3600
out={'impact_full_recalculation_max_error':float(abs(expected-d.impact_score).max()),'actor_max_error':float(abs(actor-d.actor_power).max()),'velocity_max_error':float(abs(velocity-d.velocity_component).max()),'followers_defaulted':int(d.followers_defaulted.sum()),'engagement_defaulted':int(d.engagement_defaulted.sum()),'negative_event_ages':int((age<0).sum()),'decay_multiplier_above_one':int((d.legacy_decay_multiplier>1).sum()),'regime_zero_count':int(d.regime_align.eq(0).sum()),'source_tiers':'Heuristic source string mapping, not independently verified tiers','velocity':'Full-archive engagement standardization; unsuitable for causal historical forecasting without correction','engagement_availability':'Not verified at publication','E1B_use':'These legacy impact components are not inputs to E1B','weights':'Heuristic, not independently calibrated'};(b/'results/IMPACT_AUDIT_SUMMARY.json').write_text(json.dumps(out,indent=2));print(json.dumps(out,indent=2))
